import{_ as t,o as e,c as p,a2 as r}from"./chunks/framework.F7eQ-ohH.js";const n="/bzygq/assets/73d7a54ecf2d43caa1024ecdef590f6a.C5JidtwC.png",o="/bzygq/assets/d11a032ec55f4f99ad2c6b33642dd2bc.C_wdJYn8.png",d="/bzygq/assets/2cf10c236c8f4c759fcd8f254501e4cc.BCYoPN7e.png",i="/bzygq/assets/c9e37b848042488da1b54c17c09f650c.Dmaj3PiT.png",h="/bzygq/assets/f7d139e261bb4bbd908044b0f923aeb6.BbMwZXQo.png",A=JSON.parse('{"title":"RAG效果评估、幻觉控制与项目表达","description":"","frontmatter":{},"headers":[],"relativePath":"AI应用开发/三、RAG教程/RAG效果评估、幻觉控制与项目表达.md","filePath":"AI应用开发/三、RAG教程/RAG效果评估、幻觉控制与项目表达.md","lastUpdated":1788928265000}'),l={name:"AI应用开发/三、RAG教程/RAG效果评估、幻觉控制与项目表达.md"};function s(c,a,b,R,m,_){return e(),p("div",null,[...a[0]||(a[0]=[r('<h1 id="rag效果评估、幻觉控制与项目表达" tabindex="-1">RAG效果评估、幻觉控制与项目表达 <a class="header-anchor" href="#rag效果评估、幻觉控制与项目表达" aria-label="Permalink to &quot;RAG效果评估、幻觉控制与项目表达&quot;">​</a></h1><p><strong>RAG效果评估、幻觉控制与项目表达</strong></p><p>学完 RAG 的文档解析、Chunk 切分、Embedding、向量检索、混合检索和 Rerank 之后，还差最后一块：怎么判断这个系统真的可用。</p><p>很多同学做知识库问答 Demo 时，容易把“能回答几个问题”当成效果评估。实际项目里，这样是不够的。RAG 的答案如果错了，原因可能不在模型，而在文档没解析干净、Chunk 切得太碎、Metadata 丢了、向量召回没命中、Rerank 排错、Prompt 没约束住，甚至是知识库本身没有答案。</p><p>所以 RAG 评估不能只看最终回答，而要把链路拆开看：先看正确材料有没有被找出来，再看材料有没有排到前面，再看答案是否被材料支持，最后看引用、拒答和日志闭环是否可靠。能把这套链路讲清楚，RAG 项目才不像“调了一个 LangChain 示例”，而更像真正做过企业知识库问答系统。</p><p>评估到底在评估什么</p><p>RAG 的目标不是让大模型“看起来答得像”，而是让它在给定知识库范围内，稳定地找到依据、基于依据作答，并在依据不足时主动收住。这个目标天然包含三层评估。</p><p>第一层是检索质量。用户的问题进入系统后，正确的文档片段是否进入 Top-K 候选结果，是后面所有能力的前提。如果召回阶段就没有找到依据，后面的 Prompt 再好也只能让模型更礼貌地猜。</p><p>第二层是生成质量。模型拿到材料后，是否能提取正确结论、保留关键条件、避免把多个片段的内容混在一起，是答案能不能被业务接受的核心。这里不能只看语句是否通顺，而要看结论是否被材料支持。</p><p>第三层是工程可控性。企业 RAG 不是一次性问答，而是持续运行的系统，所以要看引用是否可追溯、无依据时能否拒答、权限过滤是否生效、日志能否支持问题复盘。</p><p><img src="'+n+'" alt=""></p><p>考试或面试里问“怎么评估 RAG 效果”，不要只背 Recall@K、MRR 这些指标。更好的回答是：先拆链路，再选指标。检索阶段看命中和排序，生成阶段看正确性和依据一致性，上线阶段看引用、拒答、反馈和日志。</p><h1 id="二、先做错误归因-再谈优化" tabindex="-1">二、先做错误归因，再谈优化 <a class="header-anchor" href="#二、先做错误归因-再谈优化" aria-label="Permalink to &quot;二、先做错误归因，再谈优化&quot;">​</a></h1><p>RAG 的难点在于：最终答案错了，不代表模型本身错了。一个看似简单的错误，可能来自前面很多环节。</p><p>比如用户问“试用期请假是否影响转正”，系统答成了“不会影响”。这句话可能有多种来源：知识库里确实没有试用期制度；文档里有制度但解析时表格丢了；Chunk 把“请假”和“转正条件”切到两个片段里；向量检索只召回了假期制度，没有召回转正规则；Rerank 把不相关片段排到前面；Prompt 没要求材料不足时拒答；模型最后又按常识补了一句。</p><p>因此，评估 RAG 要先建立错误归因视角：不要看到答案错就只改 Prompt，也不要看到召回差就马上换模型。正确做法是沿着链路查证据。</p><p><img src="'+o+'" alt=""></p><p>这张图的意思很简单：RAG 评估要能定位“错在哪里”。如果正确材料没有进入候选集，优先改文档处理、Chunk、Embedding 或召回策略；如果正确材料进来了但排序靠后，优先改混合检索和 Rerank；如果材料正确但答案乱编，优先改 Prompt 约束、引用格式和答案校验；如果答案正确但用户不可接受，就要看表达、来源展示和业务流程衔接。</p><h1 id="三、检索质量-先看有没有找到正确依据" tabindex="-1">三、检索质量：先看有没有找到正确依据 <a class="header-anchor" href="#三、检索质量-先看有没有找到正确依据" aria-label="Permalink to &quot;三、检索质量：先看有没有找到正确依据&quot;">​</a></h1><p>检索质量评估的核心问题只有一个：系统有没有把能回答问题的材料找出来。</p><p>基础做法是准备一批标准问题集，每个问题都人工标注对应依据。例如“试用期员工请假是否影响转正”对应《员工手册》第 3 章和《转正管理办法》第 5 条。然后让系统跑一遍，看这些依据是否出现在 Top-3、Top-5 或 Top-10 结果中。</p><p>这里常见的 Recall@K、Precision@K、MRR 可以这样理解。Recall@K 关注“正确材料有没有进来”，Precision@K 关注“召回结果里有多少是真相关”，MRR 关注“第一条正确材料排得靠不靠前”。在企业知识库问答里，Recall@K 通常比 Precision@K 更基础，因为正确依据没进来，答案就没有根。</p><p>但是也不能只追求多召回。Top-K 太大时，虽然正确材料更容易进来，但无关材料也会变多，后续上下文会变脏，模型更容易被噪声带偏。所以检索评估要同时看“命中”和“噪声”：既要把正确依据找回来，也要控制无关片段不要挤占上下文。</p><p><img src="'+d+'" alt=""></p><p>实际项目里可以先做一个小而稳定的评估集：覆盖高频问题、边界问题、无答案问题、权限问题和多文档综合问题。评估集不一定一开始很大，但必须有标准依据，否则所有优化都只能靠感觉。</p><h1 id="四、答案质量-重点看是否被材料支持" tabindex="-1">四、答案质量：重点看是否被材料支持 <a class="header-anchor" href="#四、答案质量-重点看是否被材料支持" aria-label="Permalink to &quot;四、答案质量：重点看是否被材料支持&quot;">​</a></h1><p>答案质量不是“写得像不像人话”，而是看答案和材料之间有没有支撑关系。</p><p>一个合格的 RAG 答案至少要满足几个要求。结论要正确，不能和资料冲突；关键条件要完整，不能只说一半；引用要能对应原文，不能随便挂一个来源；材料不足时要拒答，不能用常识补齐；如果材料之间存在冲突，系统要提示冲突，而不是强行合成一个确定结论。</p><p>这里最容易被忽视的是“依据一致性”。模型可能给出一个业务上看起来合理的答案，但召回材料里根本没有这句话。对 RAG 来说，这仍然是幻觉，因为它没有基于当前知识库作答。</p><p>评估答案时，可以把每条回答拆成若干关键结论，再逐条检查是否能在召回片段中找到支撑。比如回答里出现“试用期累计请假超过 5 天会顺延转正”，那就要能在引用片段里找到“累计请假”“超过 5 天”“顺延转正”这些关键依据。只要关键条件缺了一项，答案就不能算完全可靠。</p><p>Prompt 就能解决</p><p>RAG 能降低幻觉，但不能自动消灭幻觉。原因很直接：RAG 只是把外部材料放进上下文，最终仍然是大模型在生成答案。只要材料不完整、检索不准、Prompt 约束弱，模型仍然可能补全、联想、混合甚至编造。</p><p>幻觉控制要分层做。第一层是知识库侧，保证文档解析、Chunk、Metadata 和权限过滤可靠；第二层是检索侧，提高相关材料命中率，减少无关片段噪声；第三层是生成侧，用 Prompt 明确“只能基于材料回答”“无依据要拒答”“关键结论要带来源”；第四层是校验侧，对答案和引用做一致性检查；第五层是审计侧，记录问题、召回片段、最终 Prompt、模型回答和用户反馈。</p><p><img src="'+i+'" alt=""></p><p>一个常用的 Prompt 约束可以写成这样：</p><table tabindex="0"><thead><tr><th>Plain Text请只基于参考资料回答问题。如果参考资料中没有足够依据，请回答“当前资料不足，无法确认”。不要使用参考资料之外的常识进行补充。回答中的关键结论需要标注对应来源。如果不同资料之间存在冲突，请说明冲突点，不要强行给出唯一结论。</th></tr></thead></table><p>这段 Prompt 不是为了让模型变“聪明”，而是为了缩小模型自由发挥的空间。工程上还要配合引用来源、拒答策略、答案校验和日志审计，才能把幻觉风险降到可控范围。</p><h1 id="六、上线后的评估闭环" tabindex="-1">六、上线后的评估闭环 <a class="header-anchor" href="#六、上线后的评估闭环" aria-label="Permalink to &quot;六、上线后的评估闭环&quot;">​</a></h1><p>RAG 项目上线后，评估不应该停止。真实用户的问题会不断暴露新的问题类型，比如问法更口语、业务缩写更多、跨文档问题更多、权限边界更复杂。只有把日志和反馈留下来，系统才有持续优化的抓手。</p><p>一个可落地的评估闭环通常包括五步：先维护标准问题集和标准依据；再定期跑离线评测，看检索和答案指标；上线后记录真实问题、召回结果、Prompt 和回答；对差评、投诉和人工纠错样本做归因；最后把问题反向用于文档补充、切分调整、检索策略优化、Rerank 调整和 Prompt 改写。</p><p><img src="'+h+'" alt=""></p><p>日志字段也要围绕排查问题设计。只记录最终答案是不够的，至少要能看到原始问题、改写后的查询、召回片段、Rerank 分数、最终 Prompt、模型输出、引用来源、用户身份和反馈结果。这样当用户说“答案不对”时，团队才能知道是资料没有、召回不到、排序不准，还是模型没有按材料回答。</p><p>项目怎么写进简历</p><p>简历里不要只写：</p><table tabindex="0"><thead><tr><th>Plain Text使用 LangChain + 向量数据库实现知识库问答。</th></tr></thead></table><p>这句话只能说明你用过工具，不能说明你理解 RAG 的工程链路。更好的写法是把“文档入库、检索增强、生成约束、效果评估”都写出来：</p><table tabindex="0"><thead><tr><th>Plain Text参与企业知识库问答系统建设，负责文档入库、检索增强和问答链路设计。系统支持 PDF、Word、Markdown 等资料解析，对文档进行结构化切分并生成 Embedding 写入向量数据库；用户提问后通过 Query Rewrite、混合检索和 Rerank 召回相关片段，再结合 Prompt 约束生成带引用来源的回答，并记录召回结果、答案日志和用户反馈用于效果评估与持续优化。</th></tr></thead></table><p>如果想突出后端能力，可以补充：</p><table tabindex="0"><thead><tr><th>Plain Text工程实现上封装了文档上传、解析任务、向量入库、检索服务、模型调用和日志审计等接口，并通过 Metadata 实现文档分类、来源追踪和权限过滤，提升知识库问答系统的可维护性和可追溯性。</th></tr></thead></table><p>如果想突出效果优化，可以写：</p><table tabindex="0"><thead><tr><th>Plain Text针对知识库问答中召回不准、答案无依据和引用不稳定等问题，构建标准问题集进行离线评测，按检索命中、排序质量、答案依据一致性和拒答能力定位问题，并通过 Chunk 优化、Query Rewrite、混合检索、Rerank 和 Prompt 约束持续提升回答可靠性。</th></tr></thead></table><p>images/rag_project_expression_redraw.png</p><p>面试官真正想听的不是你“接了哪个模型 API”，而是你能不能讲清：数据怎么进来、问题怎么检索、答案怎么约束、错误怎么定位、效果怎么评估、系统怎么持续变好。</p><h1 id="八、面试表达模板" tabindex="-1">八、面试表达模板 <a class="header-anchor" href="#八、面试表达模板" aria-label="Permalink to &quot;八、面试表达模板&quot;">​</a></h1><p>如果面试官问“RAG 为什么能降低幻觉”，可以这样答：</p><table tabindex="0"><thead><tr><th>Plain TextRAG 通过外部知识库给模型提供可检索的上下文，让模型回答时不完全依赖参数记忆。但它只能降低幻觉，不能自动消灭幻觉，因为召回错误、材料不足、上下文噪声和 Prompt 约束不足都会导致模型继续编造。所以工程上要结合检索命中评估、引用来源、材料不足拒答和答案一致性校验来控制风险。</th></tr></thead></table><p>如果问“你怎么评估 RAG 效果”，可以这样答：</p><table tabindex="0"><thead><tr><th>Plain Text我会把 RAG 评估拆成检索、生成和上线反馈三层。检索层看标准依据是否进入 Top-K，以及正确材料是否排得靠前；生成层看答案是否正确、完整、被材料支持，引用是否对应原文；上线后记录用户问题、召回片段、Prompt、回答和反馈，通过错误归因反向优化文档处理、召回策略、Rerank 和 Prompt。</th></tr></thead></table><p>如果问“RAG 召回到了错误材料怎么办”，可以这样答：</p><table tabindex="0"><thead><tr><th>Plain Text我会先看错误发生在召回前还是召回后。如果正确材料没有进入候选集，优先检查文档解析、Chunk 切分、Embedding、Query Rewrite 和混合检索策略；如果正确材料进来了但排序靠后，就重点优化 Rerank 和融合排序；如果材料正确但答案仍然乱编，就加强 Prompt 约束、引用生成和答案一致性校验。</th></tr></thead></table><h1 id="九、最后怎么总结" tabindex="-1">九、最后怎么总结 <a class="header-anchor" href="#九、最后怎么总结" aria-label="Permalink to &quot;九、最后怎么总结&quot;">​</a></h1><p>RAG 基础学到这里，重点已经不是会不会调向量数据库，而是能不能把它讲成一个可评估、可追踪、可迭代的工程系统。</p><p>一个完整的 RAG 项目应该包含离线文档处理、在线检索增强、模型生成约束、引用来源追踪、幻觉控制、日志审计和效果评估。检索决定模型有没有证据，Prompt 决定模型如何使用证据，评估决定系统能不能持续变好。</p><p>面试时能把这条主线讲清楚，就说明你理解的不是一个 Demo，而是一套企业 LLM 应用从“能跑”到“可用”的落地过程。</p>',64)])])}const G=t(l,[["render",s]]);export{A as __pageData,G as default};
